	@Override
	public JSONArray getUserTicketID(String details, String selecttype) {
		System.out.println("select type ::" + selecttype);
		String LoginUser = null;
		String loginUserCompany = null;
		int days = 0;

		try {
			ServletRequestAttributes requestAttributes = (ServletRequestAttributes) RequestContextHolder
					.getRequestAttributes();
			HttpSession session = requestAttributes.getRequest().getSession();
			LoginUser = session.getAttribute("username").toString();
			loginUserCompany = session.getAttribute("companyname").toString();
		} catch (Exception e) {
			e.printStackTrace();
		}

		JSONArray array1 = new JSONArray();

		try {
			if (!details.equals("all")) {

				if (details.equals("lastday")) {
					days = 1;
				}

				else if (details.equals("lastweek")) {
					days = 7;
				} else if (details.equals("lastmonthFinal")) {
					days = 30;
				} else if (details.equals("lastthreemonth")) {
					days = 90;
				} else if (details.equals("lastsixmonth")) {
					days = 180;
				}

				String query = "SELECT DISTINCT vlx_id FROM TrackingMaster WHERE STR_TO_DATE(raisedate,'%d-%m-%Y %H:%i:%s') >= NOW() - INTERVAL "
						+ days + " DAY AND ";

				if (selecttype.equals("Purchase Order")) {

					query += "vlx_id LIKE 'PO-%'"; // Filter rows where 'vlx_id' starts with 'PO-'

				} else if (selecttype.equals("Velox Proposal")) {
					query += "vlx_id LIKE 'VP-%'";

				} else {
					query += "1=1"; // Default condition to include all rows
				}

				query += " ORDER BY STR_TO_DATE(raisedate,'%d-%m-%Y %H:%i:%s') DESC";

				List<Object> dataList = sessionFactory.getCurrentSession().createSQLQuery(query).list();

				for (Object vlxId : dataList) {
					if (vlxId != null) {
						String vlxIdStr = vlxId.toString();
						array1.put(vlxIdStr);
					}
				}
			} else {
				List<Object> dataList = sessionFactory.getCurrentSession()
						.createSQLQuery("SELECT DISTINCT vlx_id FROM TrackingMaster WHERE submittedby='" + LoginUser
								+ "' ORDER BY STR_TO_DATE(raisedate,'%d-%m-%Y %H:%i:%s') DESC")
						.list();

				for (Object vlxId : dataList) {
					if (vlxId != null) {
						String vlxIdStr = vlxId.toString();
						array1.put(vlxIdStr);
					}
				}
			}
		} catch (Exception e) {
			e.printStackTrace();
		}

		return array1;
	}

