				arrayobj.put("PRIORITY", ticketDrive.getPRIORITY());
				arrayobj.put("SEVERITY", ticketDrive.getSEVERITY());
				arrayobj.put("REQUESTTYPE", ticketDrive.getREQUEST_TYPE());
				arrayobj.put("APPROVALLEVEL", ticketDrive.getAPPROVAL_LEVEL());
