	@Override
	public String updateLoginUserProfile(String username, String cname, String site, String location, String dname,
			String subDepartment, String emailid, String cno, String designation) {
		String output = "";
		try {
			Query query = sessionFactory.getCurrentSession()
					.createQuery("from loginmaster where USERNAME=:u AND COMPANY=:COMPANY");
			query.setParameter("u", username);
			query.setParameter("COMPANY", cname);
			loginmaster data = (loginmaster) query.uniqueResult();
			if (data != null) {
				// System.out.println("AD RECORD EXISTS");
				//////////////////// UPDATE RECORD /////////////////////
				Query forupdate = sessionFactory.getCurrentSession()
						.createQuery("update loginmaster set BRANCH='" + site + "' ,DEPARTMENT='" + dname
								+ "',LOCATION='" + location + "' ,SUB_DEPARTMENT='" + subDepartment + "',PHONE='" + cno
								+ "' where USERNAME='" + username + "' and COMPANY='" + cname + "'");
				int i = forupdate.executeUpdate();
				// System.out.println(" success for "+i);
				output = "success";
			}
		} catch (Exception e) {
			output = "error";
			// System.out.println("ERROR FOUND: ");
			e.printStackTrace();
		}

		return output;
	}

