					for (String emailValue : submitterEmails) {
						submitterEmailAddresses.append(emailValue).append(", ");
					}

					// Remove the trailing comma and space, if any
					String resultUserEmails = emailAddresses.toString().replaceAll(", $", "");
					String resultFullNames = fullNames.toString().replaceAll(", $", "").trim();
					String resultAuthorizerEmails = authorizerEmailAddresses.toString().replaceAll(", $", "");
					String resultSubmitterEmails = submitterEmailAddresses.toString().replaceAll(", $", "");

					System.out.println("Resulting Email Addresses for Users: " + resultUserEmails);
					System.out.println("Resulting Full Names for Users: " + resultFullNames);
					System.out.println("Resulting Email Addresses for Authorizer: " + resultAuthorizerEmails);
					System.out.println("Resulting Email Addresses for Submitter: " + resultSubmitterEmails);

