					mail m = new mail();
					String MD_Emial = MD_Emial();
					String JD_Emial = JD_Emial();
					String ProHead_Emial = ProHead_Emial();
					// Pass the resultUserEmails, resultAuthorizerEmails, and resultSubmitterEmails
