	private static JSONArray convertStringToJsonArray(String inputString) {
		JSONArray jsonArray = new JSONArray();
		String[] elements = inputString.split(",");

		for (int i = 0; i < elements.length; i += 3) {
			JSONArray subArray = new JSONArray();
			subArray.put(elements[i]);
			subArray.put(elements[i + 1]);
			subArray.put(elements[i + 2]);
			jsonArray.put(subArray);
		}

		return jsonArray;
	}

