	private String ProductManager_Emial(String crno) {
		// TODO Auto-generated method stub

		String mddetailsEmailAddresses = null;
		Session session = getSession();

		Query mddetails = session.createSQLQuery(
				"SELECT DISTINCT lm.EMAIL FROM loginmaster lm WHERE lm.FULL_NAME IN (SELECT DISTINCT ImplementerName FROM productmaster WHERE ImplementerName != ''\r\n"
						+ " AND FIND_IN_SET(SECURITY_SOLTION, (SELECT securityToolName FROM \r\n"
						+ " purchaseorder WHERE vlx_id = '" + crno + "')))");
//			Query mddetails = session.createQuery(	"SELECT DISTINCT lm.EMAIL FROM loginmaster lm WHERE lm.FULL_NAME IN (SELECT DISTINCT ImplementerName FROM ProductMaster WHERE ImplementerName != '' AND FIND_IN_SET(SECURITY_SOLTION, (SELECT SecurityToolName FROM PurchaseOrder WHERE vlx_id = '"+crno+"')))");

//			mddetails.setParameter("authname", Authorizer);
		List<String> mddetailsEmails = mddetails.list();

		// Separate the results into emailAddresses for Authorizer
		mddetailsEmailAddresses = new String();

		for (String emailValue : mddetailsEmails) {
			mddetailsEmailAddresses = emailValue;
		}

		return mddetailsEmailAddresses;

	}

