	@Override
	public String RejectRevisedProposalSM(String crno, String company, String rejectreason, String sMnote, String uname,
			String tid) {
		String output = "null";

		int srno = Integer.parseInt(tid);
		String stats = "NA";
		String updateStatus = "";
		String swalStatus = "";
		String getCheckedDate = "NA";
		String getVlx_status = "NA";
		String getCheckedby = "NA";
		String submittedby = "NA";
		String tMRaisedate = null;
		String tMSubmittedby = null;
		String tMAuthorizedDate = null;
		String tMAuthorizedby = null;
		String tMApproveddate = null;
		String tMApprovedby = null;

		if (sMnote == null || sMnote.equalsIgnoreCase("null") || sMnote.equalsIgnoreCase("")) {
			sMnote = "NA";
			System.out.println("cinote****==" + sMnote);
		}

		try {

			Criteria q1 = sessionFactory.getCurrentSession().createCriteria(ReviseProposal.class);
			q1.add(Restrictions.eq("vlx_id", crno));
			q1.add(Restrictions.eq("SR_NO", srno));

			List<ReviseProposal> vpList = q1.list();

			System.out.println("All CI-scheduleList are::: " + vpList);
			for (ReviseProposal a : vpList) {
				getCheckedDate = a.getCheckedDate();
				getVlx_status = a.getVlx_status();
				getCheckedby = a.getCheckedby();
				submittedby = a.getSubmittedby();
			}

			Date date = null;
			date = new Date();
			SimpleDateFormat formatter = new SimpleDateFormat("dd-MM-yyyy HH:mm");
			String mysqldate = formatter.format(date);

			if (getVlx_status.equalsIgnoreCase("Sent For SALES Approval")) {

				updateStatus = "Raised VP Rejected By SM";
				swalStatus = "success";
			}

			// Update CRf
			if (!updateStatus.equalsIgnoreCase("")) {

				// Update VeloxProposal

				String hql = "update ReviseProposal set SMRejectedReason= :rejReason,vlx_status= :com1,rejectedBySM= :com2,rejectedSMDate= :com4,SMNote= :sMnote WHERE vlx_id= :crno AND SR_NO= :tid";
				Query q = sessionFactory.getCurrentSession().createQuery(hql);
				q.setParameter("rejReason", rejectreason);
				q.setParameter("com1", updateStatus);
				q.setParameter("com2", uname);
				q.setParameter("com4", mysqldate);
				q.setParameter("sMnote", sMnote);
				q.setParameter("crno", crno);
				q.setParameter("tid", srno);

				int i = q.executeUpdate();
				if (i > 0) {

					System.out.println("Updated");
					output = "success";

				} else {
					System.out.println("Not Updated");
					output = "fail";
				}
			}

			// Tracking master
			try {

				Criteria q2 = sessionFactory.getCurrentSession().createCriteria(TrackingMaster.class);
				q2.add(Restrictions.eq("vlx_id", crno));
				q2.add(Restrictions.eq("vlx_status", getVlx_status));

				List<TrackingMaster> tracMasList = q2.list();

				System.out.println("All CI-scheduleList are::: " + tracMasList);
				for (TrackingMaster a : tracMasList) {

					if (a.getRaisedate() == null || a.getRaisedate().contentEquals("")) {
						tMRaisedate = "";
					} else {
						tMRaisedate = a.getRaisedate();
					}
					if (a.getSubmittedby() == null || a.getSubmittedby().contentEquals("")) {
						tMSubmittedby = "";
					} else {
						tMSubmittedby = a.getSubmittedby();
					}
					if (a.getApproveddate() == null || a.getApproveddate().contentEquals("")) {
						tMApproveddate = "";
					} else {
						tMApproveddate = a.getApproveddate();
					}
					if (a.getApprovedby() == null || a.getApprovedby().contentEquals("")) {
						tMApprovedby = "";
					} else {
						tMApprovedby = a.getApprovedby();
					}
					if (a.getAuthorizedDate() == null || a.getAuthorizedDate().contentEquals("")) {
						tMAuthorizedDate = "";
					} else {
						tMAuthorizedDate = a.getAuthorizedDate();
					}
					if (a.getAuthorizedby() == null || a.getAuthorizedby().contentEquals("")) {
						tMAuthorizedby = "";
					} else {
						tMAuthorizedby = a.getAuthorizedby();
					}

				}

				Session s1 = getSession();

				int srno2 = 0;
				try {
					Criteria crit1 = sessionFactory.getCurrentSession().createCriteria(TrackingMaster.class)
							.setProjection(Projections.max("SR_NO"));
					Integer srno3 = (Integer) crit1.uniqueResult();

					if (srno3 != null) {
						srno2 = srno3.intValue();
						srno2 = srno2 + 1;

					} else {
						srno2 = 1;

					}
				} catch (Exception e) {

					e.printStackTrace();

				}

				Date date1 = new Date();
				SimpleDateFormat formatter1 = new SimpleDateFormat("dd-MM-yyyy HH:mm:ss");
				String mysqldate1 = formatter1.format(date1);

				TrackingMaster trackingMaster = new TrackingMaster();

				trackingMaster.setSR_NO(srno2);
				trackingMaster.setVlx_id(crno);
				trackingMaster.setVlx_status("Raised VP Rejected By SM");
				trackingMaster.setRejectedDateSM(mysqldate);
				trackingMaster.setCurrentUpdatedTime(mysqldate1);
				trackingMaster.setRejectedBySM(uname);
				trackingMaster.setRaisedate(tMRaisedate);
				trackingMaster.setSubmittedby(tMSubmittedby);
				trackingMaster.setAuthorizedDate(tMAuthorizedDate);
				trackingMaster.setAuthorizedby(tMAuthorizedby);
				trackingMaster.setApproveddate(tMApproveddate);
				trackingMaster.setApprovedby(tMApprovedby);
				sessionFactory.getCurrentSession().save(trackingMaster);

				output = "success";

			} catch (Exception e) {
				e.printStackTrace();
				// TODO: handle exception
			}

			// code start
			try {
				String sales_ini = uname;
				System.out.println("sales_ini" + sales_ini);
				// start
				if (uname.equals(sales_ini)) {

					// Assuming getSession() returns a Hibernate Session
					Session session = getSession();

					List<loginmaster> allUsers = new ArrayList<>();

					// Query to get distinct email addresses based on USERNAME
					Query qByUsername = session.createQuery(
							"SELECT DISTINCT EMAIL, FULL_NAME FROM loginmaster WHERE USERNAME IN (:uname)");
					qByUsername.setParameter("uname", uname);
					List<Object[]> userResults = qByUsername.list();

					// Separate the results into emailAddresses and fullNames
					StringBuilder emailAddresses = new StringBuilder();
					StringBuilder fullNames = new StringBuilder();

					for (Object[] result : userResults) {
						String emailValue = (String) result[0];
						String fullNameValue = (String) result[1];

						emailAddresses.append(emailValue).append(", ");
						fullNames.append(fullNameValue).append(", ");
					}

					// Query to get distinct email addresses based on FULL_NAME
					Query qByFullName = session
							.createQuery("SELECT DISTINCT EMAIL FROM loginmaster WHERE USERNAME IN (:authname)");
					qByFullName.setParameter("authname", submittedby);
					List<String> authorizerEmails = qByFullName.list();

					// Separate the results into emailAddresses for Authorizer
					StringBuilder authorizerEmailAddresses = new StringBuilder();

					for (String emailValue : authorizerEmails) {
						authorizerEmailAddresses.append(emailValue).append(", ");
					}

					// Remove the trailing comma and space, if any
					String resultUserEmails = emailAddresses.toString().replaceAll(", $", "");
					String resultFullNames = fullNames.toString().replaceAll(", $", "").trim();
					String resultAuthorizerEmails = authorizerEmailAddresses.toString().replaceAll(", $", "");

					System.out.println("Resulting Email Addresses for Users: " + resultUserEmails);
					System.out.println("Resulting Full Names for Users: " + resultFullNames);
					System.out.println("Resulting Email Addresses for Authorizer: " + resultAuthorizerEmails);

					String MD_Emial = MD_Emial();
					String JD_Emial = JD_Emial();
					String ProHead_Emial = ProHead_Emial();
					// Mail start
					mail m = new mail();

					// Pass the resultUserEmails and resultAuthorizerEmails to the Send_mail method
					if (!resultUserEmails.isEmpty()) {
						String userMailStatus = m.Send_mailRejectVPRevised(resultFullNames, crno, resultUserEmails,
								resultAuthorizerEmails, rejectreason, MD_Emial, JD_Emial, ProHead_Emial);
						System.out.println("User Mail Status: " + userMailStatus);
					} else {
						System.out.println("No email addresses found for users.");
					}

				}
			} catch (Exception e) {
				e.printStackTrace();
				// Handle the exception as needed
			}
			// code end
			// mail start
//			  mail m = new mail();
//			 String Mail_StatusRejectvp=m.Send_mailRejectVP(tid);
//			 
//			 System.out.println("Mail_StatusVP Mail_StatusVP : "+Mail_StatusRejectvp);

		} catch (Exception e3) {
			e3.printStackTrace();
		}

		return output;
	}

