	@Override
	public String ApproveManualProposalLicenseMD(String crno, String status, String tid, String uname, String company,
			String MDnote) {

		String output = "null";
		String getSubmittedDate = "NA";
		String getVL_STATUS = "NA";
		String PO_INITIATOR_NAME = "NA";
		String FIRST_APPROVER_NAME = "NA";

		String updateStatus = "";
		String swalStatus = "";
		int srno = Integer.parseInt(tid);

		try {

			Criteria q1 = sessionFactory.getCurrentSession().createCriteria(VELOXPROPOSAL.class);
			q1.add(Restrictions.eq("vlx_id", crno));
			q1.add(Restrictions.eq("SR_NO", srno));

			List<VELOXPROPOSAL> vpList = q1.list();

			System.out.println("All CI-scheduleList are::: " + vpList);
			for (VELOXPROPOSAL a : vpList) {

				getVL_STATUS = a.getVlx_status();
				PO_INITIATOR_NAME = a.getPO_INITIATOR_NAME();
				FIRST_APPROVER_NAME = a.getFIRST_APPROVER_NAME();

			}

			Date date = null;
			date = new Date();
			SimpleDateFormat formatter = new SimpleDateFormat("dd-MM-yyyy HH:mm");
			String mysqldate = formatter.format(date);

			if (getVL_STATUS.equalsIgnoreCase("Manual Proposal SM Approved")) {

				updateStatus = "Manual Proposal MD Approved";
				swalStatus = "success";
			}

			System.out.println("updateStatus " + updateStatus);
			// Update Purchase Order
			if (!updateStatus.equalsIgnoreCase("")) {
				String hql = "update VELOXPROPOSAL set vlx_status= :com1,authorizedby= :com2,authorizedDate= :com3,MDNote= :com4"
						+ " WHERE vlx_id= :crno AND SR_NO= :tid";
				Query q = sessionFactory.getCurrentSession().createQuery(hql);
				q.setParameter("com1", updateStatus);
				q.setParameter("com2", uname);
				q.setParameter("com3", mysqldate);
				q.setParameter("com4", MDnote);
				q.setParameter("crno", crno);
				q.setParameter("tid", srno);

				int i = q.executeUpdate();
				if (i > 0) {
					System.out.println("Updated");
					output = swalStatus;

					// mail start for MD
					try {
						String sales_ini = uname;
						System.out.println("sales_ini" + sales_ini);

						if (uname.equals(sales_ini)) {

							// Assuming getSession() returns a Hibernate Session
							Session session = getSession();

							List<loginmaster> allUsers = new ArrayList<>();

							// Query to get distinct email addresses based on USERNAME
							Query qByUsername = session.createQuery(
									"SELECT DISTINCT EMAIL, FULL_NAME FROM loginmaster WHERE USERNAME IN (:uname)");
							qByUsername.setParameter("uname", uname);
							List<Object[]> userResults = qByUsername.list();

							// Separate the results into emailAddresses and fullNames
							StringBuilder emailAddresses = new StringBuilder();
							StringBuilder fullNames = new StringBuilder();

							for (Object[] result : userResults) {
								String emailValue = (String) result[0];
								String fullNameValue = (String) result[1];

								emailAddresses.append(emailValue).append(", ");
								fullNames.append(fullNameValue).append(", ");
							}

							// Query to get distinct email addresses based on FULL_NAME
							Query qByFullName = session.createQuery(
									"SELECT DISTINCT EMAIL FROM loginmaster WHERE FULL_NAME IN (:authname)");
							qByFullName.setParameter("authname", PO_INITIATOR_NAME);
							List<String> authorizerEmails = qByFullName.list();

							// Separate the results into emailAddresses for Authorizer
							StringBuilder authorizerEmailAddresses = new StringBuilder();

							for (String emailValue : authorizerEmails) {
								authorizerEmailAddresses.append(emailValue).append(", ");
							}

							// Query to get distinct email addresses based on FULL_NAME
							Query SMFullName = session.createQuery(
									"SELECT DISTINCT EMAIL FROM loginmaster WHERE FULL_NAME IN (:authname)");
							SMFullName.setParameter("authname", FIRST_APPROVER_NAME);
							List<String> SMEmails = SMFullName.list();

							// Separate the results into emailAddresses for Authorizer
							StringBuilder SMEmailAddresses = new StringBuilder();

							for (String emailValue : SMEmails) {
								SMEmailAddresses.append(emailValue).append(", ");
							}

							// Remove the trailing comma and space, if any
							String resultUserEmails = emailAddresses.toString().replaceAll(", $", "");
							String resultFullNames = fullNames.toString().replaceAll(", $", "").trim();
							String resultAuthorizerEmails = authorizerEmailAddresses.toString().replaceAll(", $", "");
							String resultSMEmails = SMEmailAddresses.toString().replaceAll(", $", "");

							System.out.println("Resulting Email Addresses for Users: " + resultUserEmails);
							System.out.println("Resulting Full Names for Users: " + resultFullNames);
							System.out.println("Resulting Email Addresses for Authorizer: " + resultAuthorizerEmails);
							System.out.println("Resulting Email Addresses for resultSMEmails: " + resultSMEmails);
//							String MD_Emial = MD_Emial();

							String JD_Emial = JD_Emial();
							String ProHead_Emial = ProHead_Emial();

							mail m = new mail();

							// Pass the resultUserEmails and resultAuthorizerEmails to the Send_mail method
							if (!resultUserEmails.isEmpty()) {
								String userMailStatus = m.Send_mailmanualproposalMD(resultFullNames, crno,
										resultUserEmails, resultAuthorizerEmails, resultSMEmails, JD_Emial,
										ProHead_Emial);
								System.out.println("User Mail Status: " + userMailStatus);
							} else {
								System.out.println("No email addresses found for users.");
							}

						}
					} catch (Exception e) {
						e.printStackTrace();
						// Handle the exception as needed
					}

					// Mail end for MD
				} else {
					System.out.println("Not Updated");
					output = "fail";
				}
			}

		} catch (Exception e3) {
			e3.printStackTrace();
		}

		return output;
	}

