	@Override
	public String SendMailwithattachment(String crno, String tid, String uname, String company, String clientname,
			String environmentKeyNo, String ponumber, String filenameStandard,String endCustomerEmail, String podate,String distributorEmail, String partnerEmail, String linkForEmail) {
		
		System.out.println("crno" + crno);
		System.out.println("tid" + tid);

		System.out.println("uname" + uname);
		System.out.println("company" + company);
		System.out.println("clientname" + clientname);
		System.out.println("environmentKeyNo" + environmentKeyNo);
		System.out.println("ponumber" + ponumber);
		System.out.println("filenameStandard" + filenameStandard);
		System.out.println("endCustomerEmail" + endCustomerEmail);
		System.out.println("podate" +podate);

		String filenameStandards = "NA";
		String SImailadd = "NA";
		String SMmailadd = "NA";
		String UploadedFile = "NA";
		String addrow = "";

		String output = "success";
		String userMailStatus="NA" ;
		String Quantities ="";
		String ProductSuitName ="";

		int srno = Integer.parseInt(tid);

		try {
			// Retrieve data from the VELOX_LICENSE table
			Criteria q1 = sessionFactory.getCurrentSession().createCriteria(VELOX_LICENSE.class);
			q1.add(Restrictions.eq("VP_ID", crno));
			q1.add(Restrictions.eq("SR_NO", srno));
			
			
						
			List<VELOX_LICENSE> vpList = q1.list();

			System.out.println("All CI-scheduleList are::: " + vpList);

			for (VELOX_LICENSE a : vpList) {

				filenameStandards = a.getLICENSE_STATUS();
				SImailadd = a.getMAKER();
				SMmailadd = a.getCHECKER();
				UploadedFile = a.getUploadfile();
				addrow = a.getPRODUCT_DETAILS();
				
				JSONArray jsonArray = new JSONArray(addrow);
				List<Integer> quantities = new ArrayList<>();
				List<String> productsuit = new ArrayList<>();
				List<String> con = new ArrayList<>();
 				
				for (int j = 0; j < jsonArray.length(); j++) {
					JSONObject jsonObject = jsonArray.getJSONObject(j);
					
					String productsuitname = jsonObject.getString("prodname");
//					int qty = jsonObject.getInt("Quantity");
					
					
					//
					int qty=0;
					try {
					   
					    if (jsonObject.has("Quantity") && jsonObject.get("Quantity") instanceof Number) {
					        qty = jsonObject.getInt("Quantity");
					       
					    } else if (jsonObject.has("Quantity")) {
					       
					        String qtyString = jsonObject.getString("Quantity");
					        qty = Integer.parseInt(qtyString);
					        
					    } else {
					        
					        throw new JSONException("Key 'Quantity' is missing in the JSON object");
					    }
					} catch (NumberFormatException e) {
					    
					    e.printStackTrace();
					} catch (JSONException e) {
					   
					    e.printStackTrace();
					}
					//
					
					
					String mergeTwoString = productsuitname + " - " +qty;
					
					con.add(mergeTwoString);
					quantities.add(qty);
					productsuit.add(productsuitname);
					
//					ProductSuitName = String.join(", ",productsuit.stream().map(String::valueOf).collect(Collectors.toList()));
					
					Quantities = String.join(", ",con.stream().map(String::valueOf).collect(Collectors.toList()));
				}
				
				// Process each VELOX_LICENSE object if needed
			}
			
			if(!UploadedFile.isEmpty() || UploadedFile.equals("NA")) {
				// update CM Status
				String cmStatus = "Sent Mail By CM";
				String hql = "update VELOX_LICENSE set  CMSTATUS= :cmStat WHERE VP_ID= :crno AND SR_NO= :tid";
				Query q = sessionFactory.getCurrentSession().createQuery(hql);
				q.setParameter("cmStat", cmStatus);
				q.setParameter("crno", crno);
				q.setParameter("tid", srno);
				
				q.executeUpdate();
			}

			// Start sending mail for MD
			try {
				String sales_ini = uname;
				System.out.println("sales_ini" + sales_ini);

				// Check if the user initiating the action is the same as 'sales_ini'
				if (uname.equals(sales_ini)) {
					// Assuming getSession() returns a Hibernate Session
					Session session = getSession();

					// Query to get distinct email addresses based on USERNAME
					Query qByUsername = session.createQuery(
							"SELECT DISTINCT EMAIL, FULL_NAME FROM loginmaster WHERE USERNAME IN (:uname)");
					qByUsername.setParameter("uname", uname);
					List<Object[]> userResults = qByUsername.list();

					// Separate the results into emailAddresses and fullNames
					StringBuilder emailAddresses = new StringBuilder();
					StringBuilder fullNames = new StringBuilder();

					for (Object[] result : userResults) {
						String emailValue = (String) result[0];
						String fullNameValue = (String) result[1];

						emailAddresses.append(emailValue).append(", ");
						fullNames.append(fullNameValue).append(", ");
					}

					// For SI
					// Query to get distinct email addresses based on FULL_NAME
					Query qByFullName = session
							.createQuery("SELECT DISTINCT EMAIL FROM loginmaster WHERE USERNAME IN (:authname)");
					qByFullName.setParameter("authname", SImailadd);
					List<String> authorizerEmails = qByFullName.list();

					// Separate the results into emailAddresses for Authorizer
					StringBuilder authorizerEmailAddresses = new StringBuilder();

					for (String emailValue : authorizerEmails) {
						authorizerEmailAddresses.append(emailValue).append(", ");
					}
					// For SM
					// Query to get distinct email addresses based on FULL_NAME
					Query SMmail = session
							.createQuery("SELECT DISTINCT EMAIL FROM loginmaster WHERE FULL_NAME IN (:authname)");
					SMmail.setParameter("authname", SMmailadd);
					List<String> SMEmails = SMmail.list();

					// Separate the results into emailAddresses for Authorizer
					StringBuilder SMEmailAddresses = new StringBuilder();

					for (String emailValue : SMEmails) {
						SMEmailAddresses.append(emailValue).append(", ");
					}
					// for Kale
					// Query to get distinct email addresses based on FULL_NAME
					Query cmmail = session.createQuery(
							"SELECT DISTINCT EMAIL FROM loginmaster WHERE ROLE_TYPE IN ('Account_Manager')");
//					SMmail.setParameter("authname", CMmailadd);
					List<String> CMEmails = cmmail.list();

					// Separate the results into emailAddresses for Authorizer
					StringBuilder CMEmailAddresses = new StringBuilder();

					for (String emailValue : CMEmails) {
						CMEmailAddresses.append(emailValue).append(", ");
					}

					// For Customer
					// Query to get distinct email addresses based on FULL_NAME
					Query customermail = session.createQuery(
							"select ENDCUSTOMEREMAIL from VELOX_LICENSE where CLIENTNAME='" + clientname + "'");
//					SMmail.setParameter("authname", CMmailadd);
					List<String> customerEmails = customermail.list();

					// Separate the results into emailAddresses for Authorizer
					StringBuilder customermailAddresses = new StringBuilder();

					for (String emailValue : customerEmails) {
						customermailAddresses.append(emailValue).append(", ");
					}
					// Remove the trailing comma and space, if any
					String resultUserEmails = emailAddresses.toString().replaceAll(", $", "");
					String resultFullNames = fullNames.toString().replaceAll(", $", "").trim();
					String SImailid = authorizerEmailAddresses.toString().replaceAll(", $", "").trim();
					String SMmailid = SMEmailAddresses.toString().replaceAll(", $", "").trim();
					String CMmailid = CMEmailAddresses.toString().replaceAll(", $", "").trim();
					String Customermailid = customermailAddresses.toString().replaceAll(", $", "").trim();
					String MD_Emial = MD_Emial(); // Assuming MD_Emial is a method that returns an email address
					String JD_Emial = JD_Emial();
					// Create an instance of the 'mail' class
					mail m = new mail();
					System.out.println("resultUserEmails" + resultUserEmails);
					System.out.println("resultFullNames" + resultFullNames);
					System.out.println("SImailid" + SImailid);
					System.out.println("SMmailid" + SMmailid);
					System.out.println("CMmailid" + CMmailid);
					System.out.println("Customermailid" + Customermailid);
					System.out.println("endCustomerEmail" + endCustomerEmail);

					// Pass the resultUserEmails and resultAuthorizerEmails to the Send_mail method
					if (!resultUserEmails.isEmpty()) {
						 userMailStatus = m.Send_mailwithattachedfile(uname, resultFullNames, crno,
								resultUserEmails, MD_Emial, filenameStandards, SImailid, SMmailid, CMmailid,
								endCustomerEmail, JD_Emial, UploadedFile,ponumber,podate,Quantities,distributorEmail, partnerEmail, linkForEmail);
						System.out.println("User Mail Status: " + userMailStatus);
					} else {
						System.out.println("No email addresses found for users.");
					}
				}
			} catch (Exception e) {
				e.printStackTrace();
				// Handle the exception as needed
			}
			// End mail for MD
		} catch (Exception e3) {
			e3.printStackTrace();
		}

//		return output;
		System.out.println("userMailStatus"+userMailStatus);
		return userMailStatus;
	}


